export function diffLabel(d){ return d === "easy" ? "Easy" : d === "medium" ? "Medium" : "Hard"; }

/* FLAT_TEXTS — built exactly as the current app builds flatTexts: every drill
   item in order, then the 116 HCM passages appended by the exam module. */
export const FLAT_TEXTS = [];
DRILLS.forEach(function(sec){ sec.items.forEach(function(it){ FLAT_TEXTS.push(it); }); });
PASSAGE_BATCH.hcm.forEach(function(p, i){ FLAT_TEXTS.push({ id: p.tid, name: "HCM Mock " + (i + 1), text: flowText(p.text) }); });
export function textById(id){ return FLAT_TEXTS.find(function(x){ return x.id === id; }) || null; }
